$_MODULE['<{alsernetcontents}prestashop>home_0186792b617a87f4749414f9c9a45b0a'] = 'Bienvenido a la ';
$_MODULE['<{alsernetcontents}prestashop>home_c9961f0e54293d9e2288a4983d531bbd'] = 'tienda on-line líder en tu deporte y líder en precio.';
$_MODULE['<{alsernetcontents}prestashop>home_46636857295d4111681fe58299399794'] = 'Desde hace más de 60 años trabajamos para ofrecerte el mayor catálogo de productos para golf, caza, pesca, equitación, submarinismo, náutica, pádel, esquí, aventura y tiempo libre.';
$_MODULE['<{alsernetcontents}prestashop>home_200c2cb846c1e2d93dbfc292b5684b61'] = 'Selecciona tu deporte y accede a la tienda online con mayor surtido de artículos:';
$_MODULE['<{alsernetcontents}prestashop>home_05d9e57772625e8c4fe5e3659f915b26'] = 'desde un pequeño complemento de caza hasta las últimas novedades del mundo del golf. Trabajamos con las principales marcas de cada sector, nacionales y extranjeras, para poder ofrecerte total garantía en cada una de tus compras. Muchos de los productos que comercializamos, sólo pueden conseguirse en Álvarez.';
$_MODULE['<{alsernetcontents}prestashop>home_89aa4ba138fbceb2860656cb3fedd02e'] = 'Además de la mayor variedad de artículos para el deporte, en nuestra tienda online podrás encontrar secciones de compra/venta entre particulares, armas usadas, productos de segunda mano, tablones de anuncios y gran cantidad de información útil para la práctica de tu deporte… Entra, infórmate y ¡participa! Estaremos encantados de que nos hagas llegar todos los comentarios y sugerencias que desees para ayudarnos a mejorar.';
$_MODULE['<{alsernetcontents}prestashop>home_cfa32980a3967dd37fa1313a8d427e28'] = 'Y con el';
$_MODULE['<{alsernetcontents}prestashop>home_5e785b31f9a76244a682243710a9bc7e'] = 'compromiso del mejor precio.';
$_MODULE['<{alsernetcontents}prestashop>home_1949c55761873a4c95597f74aa54d77e'] = 'En Álvarez podrás comprar con la tranquilidad de que no encontrarás el mismo producto más barato en ningún otro sitio: nos comprometemos a tener siempre el mejor precio en todos nuestros artículos.';
$_MODULE['<{alsernetcontents}prestashop>home_921efc1ceb64c2aae5451a89f87eabe5'] = 'Tenemos productos y marcas que se adaptan a todos los niveles y presupuestos; desde artículos de alta gama a productos para iniciarse en cada deporte, todos ellos con el mejor precio. Además y para que no tengas que preocuparte por nada, nuestra tienda online cumple con todos los requisitos de seguridad para el tratamiento de datos personales, así como de los sistemas contra fraude más avanzados del mercado. ';
$_MODULE['<{alsernetcontents}prestashop>home_185b7b8210bec0dde2abf94111b5d5ba'] = ' ¡Total seguridad en tus compras!';
$_MODULE['<{alsernetcontents}prestashop>home_9b04b4018a34c941445a66e7e4a98e42'] = 'Máxima seguridad antes y después de la compra: si el producto adquirido no cumple con tus expectativas, podrás devolverlo sin problemas; ofrecemos una';
$_MODULE['<{alsernetcontents}prestashop>home_81d0b022c61768007ca2387ecd87a7b3'] = ' total garantía de devolución.';
$_MODULE['<{alsernetcontents}prestashop>home_6035653eb3c6e4292f7cfdd7d267535f'] = 'Si lo prefieres, también puedes realizar tus compras en nuestras tiendas físicas. Disponemos de tiendas en';
$_MODULE['<{alsernetcontents}prestashop>home_6314044c3803213e9fd3f3ecf8c90d65'] = 'Madrid';
$_MODULE['<{alsernetcontents}prestashop>home_7c96c18982d64a8bfa52cf728109db40'] = '(C/ Poeta Joan Maragall nº60 - antes Capitán Haya - y C/Diego de León nº56), y ';
$_MODULE['<{alsernetcontents}prestashop>home_dcf99827d399ec5bde6f1b30987e73ef'] = 'La Coruña';
